from fractions import Fraction
import math
from collections import deque

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_coprime_pairs(limit):
    pairs = []
    # Only check m <= n to avoid duplicates (m/n vs n/m initial set)
    for m in range(1, limit):
        for n in range(m, limit):
            if m + n < limit and gcd(m, n) == 1:
                pairs.append((m, n))
    return pairs

def simulate(m, n, max_depth=10):
    """
    Simulates the process starting with m/n and n/m to see if 1 can be generated.
    Returns a list of paths if 1 is found, otherwise None.
    """
    start_numbers = {Fraction(m, n), Fraction(n, m)}

    # Queue stores (current_set_of_numbers, depth, path_description)
    queue = deque([(start_numbers, 0, [])])

    # Visited set to prevent infinite loops/redundant computations. 
    # Since the numbers are always rational, we can store tuples of sorted unique numbers.
    def get_state_key(s):
        # Convert to sorted tuple of numerators/denominators for hashing
        return tuple(sorted([ (x.numerator, x.denominator) for x in s ]))

    visited = {get_state_key(start_numbers)}

    while queue:
        current_set, depth, path = queue.popleft()

        if depth >= max_depth:
            continue

        # Try all pairs (x, y) in the current set
        list_set = list(current_set)
        num_elements = len(list_set)

        for i in range(num_elements):
            for j in range(i, num_elements):
                x = list_set[i]
                y = list_set[j]

                # Operation 1: Arithmetic Mean (AM)
                A = (x + y) / 2

                if A == 1:
                    return path + [f"AM({x}, {y})"]

                new_set_A = current_set.union({A})
                key_A = get_state_key(new_set_A)

                if key_A not in visited:
                    visited.add(key_A)
                    new_path_A = path + [f"AM({x}, {y})"]
                    queue.append((new_set_A, depth + 1, new_path_A))

                # Operation 2: Harmonic Mean (HM)
                # Check for x+y=0 case, though not expected with positive inputs
                if x + y != 0:
                    H = (2 * x * y) / (x + y)

                    if H == 1:
                        return path + [f"HM({x}, {y})"]

                    new_set_H = current_set.union({H})
                    key_H = get_state_key(new_set_H)

                    if key_H not in visited:
                        visited.add(key_H)
                        new_path_H = path + [f"HM({x}, {y})"]
                        queue.append((new_set_H, depth + 1, new_path_H))

    return None

